 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientAuthorizationDetailsTypesAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAuthorizationDetailsTypes returns null on a freshly created holder.
     */
    public function testAuthorizationDetailsTypesNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationDetailsTypesAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAuthorizationDetailsTypesAssigned());
        $this->assertNull($holder->getAuthorizationDetailsTypes());
    }
}
